+/** Theoretical sales use and actual consumption per item over inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const byItem = new Map();
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const add = (itemId, field, qty) => {
+    const line = byItem.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    line[field] += Math.round(qty * 1000);
+    byItem.set(itemId, line);
+  };
+  for (const sale of store.data.sales) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const item of sale.ingredients) add(item.itemId, "theoretical", item.qty);
+  }
+  const batchItems = new Map(store.data.batches.map((batch) => [batch.id, batch.itemId]));
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || movement.qty <= 0 || !inRange(movement.at)) continue;
+    if (batchItems.has(movement.batchId)) add(batchItems.get(movement.batchId), "actual", movement.qty);
+  }
+  return [...byItem.values()].sort((a, b) => a.itemId - b.itemId).map(({ itemId, theoretical, actual }) => ({
+    itemId,
+    theoretical: theoretical / 1000,
+    actual: actual / 1000,
+    difference: (actual - theoretical) / 1000,
+  }));
+}
