+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Imports all new sale lines together and returns ticket and portion counts. */
+export function recordSales(store, lines) {
+  const staged = memoryStore(store.data);
+  const existing = new Set(staged.data.sales.map((sale) => sale.ticket));
+  const imported = new Set();
+  let dishes = 0;
+  for (const { row, ticket, soldAt, dishId, qty } of lines) {
+    if (existing.has(ticket)) continue;
+    try {
+      const dish = getDish(staged, dishId);
+      const ingredients = scaled(getRecipe(staged, dish.recipeId), qty).filter((item) => item.qty > 0);
+      for (const item of ingredients) {
+        consume(staged, item.itemId, item.qty, { at: soldAt, ref: `sale:${ticket}` });
+      }
+      staged.data.sales.push({ ticket, soldAt, dishId, qty, ingredients });
+      imported.add(ticket);
+      dishes += qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      if (error.code === "not_enough_stock") {
+        throw new AppError("sale_stock_shortage", { ...error.params, row });
+      }
+      throw new AppError("bad_request", { reason: `row ${row}: invalid dish or recipe (${error.code})` });
+    }
+  }
+  if (imported.size) store.data = staged.data;
+  return { tickets: imported.size, dishes };
+}
