diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..a3858f9
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,44 @@
+import { isDate } from "../dates.js";
+import { recordSales } from "../domain/sales.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const CELL = '(?:"(?:[^"]|"")*"|[^",]*)';
+const CSV_LINE = new RegExp(`^${CELL}(?:,${CELL})*$`);
+const INSTANT = /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})$/;
+
+function invalid(row, reason) {
+  return new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+function positiveInteger(field) {
+  return /^\d+$/.test(field) && Number.isSafeInteger(Number(field)) && Number(field) > 0;
+}
+
+/** Parses and imports till CSV, with one-based physical row numbers in errors. */
+export function importSales(store, text) {
+  const [header, ...rows] = text.replace(/^\uFEFF/, "").split(/\r?\n/);
+  const [columns = []] = parseCsv(header);
+  const keys = columns.map((column) => column.trim());
+  if (!CSV_LINE.test(header) || keys.length !== HEADER.length || !HEADER.every((key) => keys.includes(key))) {
+    throw invalid(1, "expected columns ticket,soldAt,dishId,qty");
+  }
+  const lines = [];
+  for (const [index, line] of rows.entries()) {
+    if (!line.trim()) continue;
+    const row = index + 2;
+    if (!CSV_LINE.test(line)) throw invalid(row, "invalid CSV");
+    const [fields] = parseCsv(line);
+    if (fields.length !== keys.length) throw invalid(row, "expected four fields");
+    const { ticket, soldAt, dishId, qty } = Object.fromEntries(keys.map((key, i) => [key, fields[i].trim()]));
+    if (!ticket) throw invalid(row, "ticket is required");
+    const match = INSTANT.exec(soldAt);
+    const time = Date.parse(soldAt);
+    if (!match || !isDate(match[1]) || !Number.isFinite(time)) throw invalid(row, "soldAt must be an ISO instant");
+    if (!positiveInteger(dishId)) throw invalid(row, "dishId must be a positive integer");
+    if (!positiveInteger(qty)) throw invalid(row, "qty must be a positive integer");
+    lines.push({ row, ticket, soldAt: new Date(time).toISOString(), dishId: Number(dishId), qty: Number(qty) });
+  }
+  return recordSales(store, lines);
+}
